document.addEventListener('DOMContentLoaded',function(){document.querySelectorAll('.cancel-btn').forEach(function(btn){btn.addEventListener('click',async function(){if(!confirm('Отменить заявку № '+btn.dataset.id+'? Это действие нельзя вернуть.'))return;await withBusy(btn,async function(){const res=await api('/api/requests/'+btn.dataset.id,'DELETE');if(res.success){toast('Заявка отменена','ok');btn.closest('.card').classList.add('removing');setTimeout(function(){location.reload();},700);}else{toast(res.message,'error');}});});});document.querySelectorAll('.review-form').forEach(function(form){form.addEventListener('submit',async function(event){event.preventDefault();const data=formData(form);const holder=form.querySelector('[data-error-for="review"]');holder.textContent='';if(!data.rating){holder.textContent='Поставьте оценку';return;}
if(!data.text){holder.textContent='Напишите текст отзыва';return;}
const button=form.querySelector('button');await withBusy(button,async function(){const res=await api('/api/requests/'+form.dataset.request+'/review','POST',data);if(res.success){toast(res.message,'ok');setTimeout(function(){location.reload();},900);}else{holder.textContent=res.message;}});});});});